<?php get_header();while(have_posts()):the_post(); ?><main id="primary"><div class="container"><?php rzz_breadcrumb(); ?></div><section class="profile-section"><div class="container profile-layout"><aside class="profile-directory"><p class="eyebrow">Our team</p><?php foreach(get_posts(['post_type'=>'team','numberposts'=>-1,'orderby'=>'menu_order','order'=>'ASC']) as $person)echo '<a '.(get_the_ID()===$person->ID?'aria-current="page" ':'').'href="'.esc_url(get_permalink($person)).'">'.esc_html($person->post_title).'</a>'; ?></aside><article class="profile-main"><?php if(has_post_thumbnail())the_post_thumbnail('rzz-portrait',['class'=>'profile-portrait','fetchpriority'=>'high']); ?><div class="profile-copy"><h1><?php the_title(); ?></h1><p class="role"><?php echo esc_html(rzz_team_role()); ?></p><div class="button-row"><?php if(is_email(rzz_meta('email'))): ?><a class="button outline" href="mailto:<?php echo esc_attr(rzz_meta('email')); ?>">Email <?php echo rzz_arrow(); ?></a><?php endif;if(rzz_meta('linkedin')): ?><a class="button outline" href="<?php echo esc_url(rzz_meta('linkedin')); ?>">LinkedIn <?php echo rzz_arrow(); ?></a><?php endif; ?></div><div class="practice-pills"><?php rzz_area_links(); ?></div><div class="prose"><?php the_content(); ?></div></div></article><aside class="profile-details light"><?php foreach(['education'=>'Education','career'=>'Career highlights','languages'=>'Languages'] as $key=>$label):if(!rzz_meta($key))continue; ?><section><h2><?php echo esc_html($label); ?></h2><ul><?php foreach(rzz_lines(rzz_meta($key)) as $line)echo '<li>'.esc_html($line).'</li>'; ?></ul></section><?php endforeach; ?><section><h2>Practice areas</h2><div class="practice-pills"><?php rzz_area_links(); ?></div></section><a class="button dark" href="<?php echo esc_url(rzz_link('contact')); ?>">Get in touch <?php echo rzz_arrow(); ?></a></aside></div></section><?php get_template_part('template-parts/principles-band'); get_template_part('template-parts/contact'); ?></main><?php endwhile;get_footer(); ?>